def dihedral(a):
 return [a, np.fliplr(a), np.flipud(a), np.rot90(a), np.rot90(a,2), np.rot90(a,3), np.flipud(np.rot90(a)), np.fliplr(np.rot90(a))]
def findmatches(D, out):
 found=[]
 for k,a in enumerate(dihedral(out)):
  loc=[]
  for i in range(D.shape[0]-a.shape[0]+1):
   for j in range(D.shape[1]-a.shape[1]+1):
    if np.array_equal(D[i:i+a.shape[0],j:j+a.shape[1]],a):loc.append((i,j))
  if loc:found.append((k,a.shape,loc))
 return found
