def transform(grid):
    g=np.asarray(grid,dtype=int)
    r0,r1=np.where(g==8)[0].min(),np.where(g==8)[0].max()
    c0,c1=np.where(g==8)[1].min(),np.where(g==8)[1].max()
    H,W=g.shape
    vals={}
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if g[r,c]!=8: continue
            candidates=[]
            for rr,cc in ((r, W+1-c),(H+1-r,c),(H+1-r,W+1-c)):
                if 0<=rr<H and 0<=cc<W and g[rr,cc]!=8:
                    candidates.append(int(g[rr,cc]))
            if candidates:
                vals[r,c]=candidates[0]
    # largest all-known rectangle in masked bounding box
    best=None
    for a in range(r0,r1+1):
      for b in range(a,r1+1):
       for x in range(c0,c1+1):
        for y in range(x,c1+1):
         if all((r,c) in vals for r in range(a,b+1) for c in range(x,y+1)):
          area=(b-a+1)*(y-x+1)
          if best is None or area>best[0]: best=(area,a,b,x,y)
    if best is None: return []
    _,a,b,x,y=best
    return [[vals[r,c] for c in range(x,y+1)] for r in range(a,b+1)]
